PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS warehouses(id INTEGER PRIMARY KEY,name TEXT NOT NULL,location TEXT NOT NULL,capacity INTEGER NOT NULL CHECK(capacity>0),manager TEXT NOT NULL,contact TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('Active','Inactive')));
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('Admin','Logistics Officer','Warehouse Staff')),warehouse_id INTEGER REFERENCES warehouses(id),CHECK(role!='Warehouse Staff' OR warehouse_id IS NOT NULL));
CREATE TABLE IF NOT EXISTS supplies(id INTEGER PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>=0),unit TEXT NOT NULL,warehouse_id INTEGER NOT NULL REFERENCES warehouses(id),minimum_stock INTEGER NOT NULL CHECK(minimum_stock>=0),expiry_date TEXT,status TEXT NOT NULL CHECK(status IN ('Active','Inactive')));
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY,vehicle_number TEXT UNIQUE NOT NULL,vehicle_type TEXT NOT NULL,driver_name TEXT NOT NULL,source TEXT,destination TEXT,dispatch_date TEXT,expected_date TEXT,status TEXT NOT NULL DEFAULT 'Available' CHECK(status IN ('Available','In Transit')));
CREATE TABLE IF NOT EXISTS requests(id INTEGER PRIMARY KEY,requester INTEGER NOT NULL REFERENCES users(id),supply_id INTEGER NOT NULL REFERENCES supplies(id),quantity INTEGER NOT NULL CHECK(quantity>0),source_warehouse INTEGER NOT NULL REFERENCES warehouses(id),destination TEXT NOT NULL,request_date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,priority TEXT NOT NULL CHECK(priority IN ('Routine','High','Urgent')),status TEXT NOT NULL DEFAULT 'Pending' CHECK(status IN ('Pending','Approved','Rejected','In Transit','Delivered')),vehicle_id INTEGER REFERENCES vehicles(id),dispatch_date TEXT,expected_date TEXT,delivered_date TEXT);
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,alert_key TEXT NOT NULL,message TEXT NOT NULL,type TEXT NOT NULL,date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,is_read INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,alert_key));
CREATE TABLE IF NOT EXISTS stock_movements(id INTEGER PRIMARY KEY,supply_id INTEGER NOT NULL REFERENCES supplies(id),user_id INTEGER NOT NULL REFERENCES users(id),quantity INTEGER NOT NULL,reason TEXT NOT NULL,date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS activities(id INTEGER PRIMARY KEY,message TEXT NOT NULL,user_id INTEGER REFERENCES users(id),date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS request_events(id INTEGER PRIMARY KEY,request_id INTEGER NOT NULL REFERENCES requests(id),status TEXT NOT NULL,date TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_supply_warehouse ON supplies(warehouse_id);
CREATE INDEX IF NOT EXISTS idx_request_status ON requests(status);
